INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8eddd953-43d5-5b16-8074-aabf22aa164a', 'France Method for producing greenhouse gas emissions balance sheets', 'Method for producing greenhouse gas emissions balance sheets', 'The policy document outlines the method for producing greenhouse gas emissions balance sheets in France, as mandated by legislative provisions. It details general principles for evaluating emissions, key steps, regulatory provisions, and reporting formats. The document covers various emission sources including stationary combustion, mobile sources, non-energy processes, biomass, and indirect emissions. It emphasizes the importance of calculating emissions factors, managing uncertainties, and addressing different emission categories. The policy aims to enhance transparency and accountability in emissions reporting.', 'The policy document outlines the method for producing greenhouse gas emissions balance sheets in France, as mandated by legislative provisions. It details general principles for evaluating emissions, key steps, regulatory provisions, and reporting formats. The document covers various emission sources including stationary combustion, mobile sources, non-energy processes, biomass, and indirect emissions. It emphasizes the importance of calculating emissions factors, managing uncertainties, and addressing different emission categories. The policy aims to enhance transparency and accountability in emissions reporting.', 'The policy document outlines the method for producing greenhouse gas emissions balance sheets in France, as mandated by legislative provisions. It details general principles for evaluating emissions, key steps, regulatory provisions, and reporting formats. The document covers various emission sources including stationary combustion, mobile sources, non-energy processes, biomass, and indirect emissions. It emphasizes the importance of calculating emissions factors, managing uncertainties, and addressing different emission categories. The policy aims to enhance transparency and accountability in emissions reporting.', 'France', 'climate', 'in_force', '2016-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_51', ARRAY['sdg13', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'france', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb9ad7ea-ece8-5fc5-9f7c-98d27dda23ed', 'France Decree of January 8, 2016 relating to the', 'Decree No. 2016-10 of January 8, 2016 relating to the “socially responsible investment” label', 'The Decree No. 2016-10 of January 8, 2016, from France establishes the ''socially responsible investment'' label for portfolio management companies, certification bodies, and investors. It defines criteria for collective investment undertakings to qualify for the label by financing entities contributing to sustainable development. The decree outlines procedures for labeling funds, the role of certification bodies, and monitoring processes. The label signifies compliance with set management criteria balancing economic performance and social-environmental impact. It becomes effective immediately upon publication, aiming to promote responsible investments in various sectors.', 'The Decree No. 2016-10 of January 8, 2016, from France establishes the ''socially responsible investment'' label for portfolio management companies, certification bodies, and investors. It defines criteria for collective investment undertakings to qualify for the label by financing entities contributing to sustainable development. The decree outlines procedures for labeling funds, the role of certification bodies, and monitoring processes. The label signifies compliance with set management criteria balancing economic performance and social-environmental impact. It becomes effective immediately upon publication, aiming to promote responsible investments in various sectors.', 'The Decree No. 2016-10 of January 8, 2016, from France establishes the ''socially responsible investment'' label for portfolio management companies, certification bodies, and investors. It defines criteria for collective investment undertakings to qualify for the label by financing entities contributing to sustainable development. The decree outlines procedures for labeling funds, the role of certification bodies, and monitoring processes. The label signifies compliance with set management criteria balancing economic performance and social-environmental impact. It becomes effective immediately upon publication, aiming to promote responsible investments in various sectors.', 'France', 'climate', 'in_force', '2016-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_6', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'france', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
