INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('71ddea0f-c3b8-518f-a06e-fff45893e7e3', 'France Law of 17 August 2015 relating to the', 'Law No. 2015-992 of 17 August 2015 relating to the energy transition for green growth (1)', 'The French Law No. 2015-992 aims to transition to a green economy by promoting energy efficiency, reducing greenhouse gas emissions, and increasing renewable energy use. It sets objectives for energy consumption reduction, industry development, and social equity while targeting all stakeholders involved in energy policy implementation.', 'The French Law No. 2015-992 aims to transition to a green economy by promoting energy efficiency, reducing greenhouse gas emissions, and increasing renewable energy use. It sets objectives for energy consumption reduction, industry development, and social equity while targeting all stakeholders involved in energy policy implementation.', 'The French Law No. 2015-992 aims to transition to a green economy by promoting energy efficiency, reducing greenhouse gas emissions, and increasing renewable energy use. It sets objectives for energy consumption reduction, industry development, and social equity while targeting all stakeholders involved in energy policy implementation.', 'France', 'climate', 'in_force', '2015-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_69', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'france', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
