INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0da00ae-dd92-5d51-906f-22f0dbdda69b', 'France Corporate governance code of listed corporations (Revised June', 'Corporate governance code of listed corporations (Revised June 2013)', 'This code stems from initiatives of the business community itself, which attaches importance to defining certain principles of good operation and transparency intended to improve management practices and to respond to the expectations of investors and the public. This new version gives rise to a consultation, in particular of the public authorities, organisations representing individual and institutional shareholders and proxy advisors.', 'This code stems from initiatives of the business community itself, which attaches importance to defining certain principles of good operation and transparency intended to improve management practices and to respond to the expectations of investors and the public. This new version gives rise to a consultation, in particular of the public authorities, organisations representing individual and institutional shareholders and proxy advisors.', 'This code stems from initiatives of the business community itself, which attaches importance to defining certain principles of good operation and transparency intended to improve management practices and to respond to the expectations of investors and the public. This new version gives rise to a consultation, in particular of the public authorities, organisations representing individual and institutional shareholders and proxy advisors.', 'France', 'climate', 'in_force', '2013-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_8', ARRAY['regulations', 'sdg11', 'mandatory', 'sdg16', 'france', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('299cddcf-6fc1-571f-b43c-96b25ad7d063', 'France Recommendations on Corporate Governance - Revised', 'Recommendations on Corporate Governance - Revised 2011', 'In 1997, with the aim of providing guidance to AFG members on the exercise of their voting rights, AFG Board of Directors also decided to create a Corporate Governance Committee, chaired since then by Jean-Pierre Hellebuyck. The Committee was allocated the responsibility of publishing a code of corporate governance. The recommendations resulting from this early work, published in 1998, were updated on several occasions. The present 2011 edition is thus the ninth version of this code.', 'In 1997, with the aim of providing guidance to AFG members on the exercise of their voting rights, AFG Board of Directors also decided to create a Corporate Governance Committee, chaired since then by Jean-Pierre Hellebuyck. The Committee was allocated the responsibility of publishing a code of corporate governance. The recommendations resulting from this early work, published in 1998, were updated on several occasions. The present 2011 edition is thus the ninth version of this code.', 'In 1997, with the aim of providing guidance to AFG members on the exercise of their voting rights, AFG Board of Directors also decided to create a Corporate Governance Committee, chaired since then by Jean-Pierre Hellebuyck. The Committee was allocated the responsibility of publishing a code of corporate governance. The recommendations resulting from this early work, published in 1998, were updated on several occasions. The present 2011 edition is thus the ninth version of this code.', 'France', 'governance', 'in_force', '2011-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_18', ARRAY['guidance_frameworks', 'sdg16', 'france', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2d8c830-58e5-5894-bbd7-023134524340', 'France Recommendations on Corporate Governance', 'Recommendations on Corporate Governance 2010', 'In 1997, with the aim of providing guidance to AFG members on the exercise of their voting rights, AFG Board of Directors also decided to create a Corporate Governance Committee, chaired since then by Jean-Pierre Hellebuyck. The Committee was allocated the responsibility of publishing a code of corporate governance. The recommendations resulting from this early work, published in 1998, were updated on several occasions. The present 2010 edition is thus the eighth version of this code.', 'In 1997, with the aim of providing guidance to AFG members on the exercise of their voting rights, AFG Board of Directors also decided to create a Corporate Governance Committee, chaired since then by Jean-Pierre Hellebuyck. The Committee was allocated the responsibility of publishing a code of corporate governance. The recommendations resulting from this early work, published in 1998, were updated on several occasions. The present 2010 edition is thus the eighth version of this code.', 'In 1997, with the aim of providing guidance to AFG members on the exercise of their voting rights, AFG Board of Directors also decided to create a Corporate Governance Committee, chaired since then by Jean-Pierre Hellebuyck. The Committee was allocated the responsibility of publishing a code of corporate governance. The recommendations resulting from this early work, published in 1998, were updated on several occasions. The present 2010 edition is thus the eighth version of this code.', 'France', 'governance', 'in_force', '2010-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_17', ARRAY['guidance_frameworks', 'sdg16', 'france', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b76de4ea-f5b6-5485-ab32-75b2a30b83ce', 'France Corporate Governance Code of Listed Corporations', 'Corporate Governance Code of Listed Corporations 2010', 'This code is concerned with the corporate governance principles resulting from the consolidation of the October 2003 AFEP and MEDEF report, the January 2007 and October 2008 AFEP and MEDEF recommendations concerning the com-pensation of executive directors of listed companies and the April 2010 AFEP and MEDEF recommendation concerning the strengthening of women representation within the boards.', 'This code is concerned with the corporate governance principles resulting from the consolidation of the October 2003 AFEP and MEDEF report, the January 2007 and October 2008 AFEP and MEDEF recommendations concerning the com-pensation of executive directors of listed companies and the April 2010 AFEP and MEDEF recommendation concerning the strengthening of women representation within the boards.', 'This code is concerned with the corporate governance principles resulting from the consolidation of the October 2003 AFEP and MEDEF report, the January 2007 and October 2008 AFEP and MEDEF recommendations concerning the com-pensation of executive directors of listed companies and the April 2010 AFEP and MEDEF recommendation concerning the strengthening of women representation within the boards.', 'France', 'climate', 'in_force', '2010-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_62', ARRAY['guidance_frameworks', 'mandatory', 'sdg5', 'france', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5b62aff2-183f-50f9-b740-96fb30b6e136', 'France Corporate Governance Code for Small and Medium-Sized Enterprises', 'Corporate Governance Code for Small and Medium-Sized Enterprises 2009', 'This code is intended to offer these companies, which often have a reference shareholding, recommendations for assessing their governance. It thus complements other codes, in particular the one proposed by AFEP and MEDEF, some of whose recommendations are not suited to them.', 'This code is intended to offer these companies, which often have a reference shareholding, recommendations for assessing their governance. It thus complements other codes, in particular the one proposed by AFEP and MEDEF, some of whose recommendations are not suited to them.', 'This code is intended to offer these companies, which often have a reference shareholding, recommendations for assessing their governance. It thus complements other codes, in particular the one proposed by AFEP and MEDEF, some of whose recommendations are not suited to them.', 'France', 'governance', 'in_force', '2009-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_10', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'france']::text[]) ON CONFLICT (id) DO NOTHING;
