INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8177209d-d722-5b2b-8741-fc3910acd36c', 'France Recommendations on Corporate Governance', 'Recommendations on Corporate Governance 2004', 'These recommendations apply to French companies whose securities are admitted to trading on a French regulated market, and their general principles apply to all investments that managers make abroad. They constitute voting criteria intended to guide managers who are members of the AFG. They are not intended to necessarily result in legislative adaptations.', 'These recommendations apply to French companies whose securities are admitted to trading on a French regulated market, and their general principles apply to all investments that managers make abroad. They constitute voting criteria intended to guide managers who are members of the AFG. They are not intended to necessarily result in legislative adaptations.', 'These recommendations apply to French companies whose securities are admitted to trading on a French regulated market, and their general principles apply to all investments that managers make abroad. They constitute voting criteria intended to guide managers who are members of the AFG. They are not intended to necessarily result in legislative adaptations.', 'France', 'governance', 'in_force', '2004-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_16', ARRAY['guidance_frameworks', 'sdg16', 'france', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
