INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc7114c3-f95a-53af-9f2b-d03187141912', 'France Law of July 17, 2001 on various social', 'Law No. 2001-624 of July 17, 2001 on various social, educational and cultural provisions', 'The French Law No. 2001-624 of July 17, 2001, focuses on various social, educational, and cultural provisions. It includes measures for unemployment compensation, reserve fund for pensioners, provisions for youth and popular education, and support for education and communication. The law aims to promote professional reintegration, aid geographical mobility, provide hiring incentives, offer training aid, and support actions for reclassification of employees. The policy targets individuals seeking employment, employers, training organizations, and the National Employment Agency. It outlines specific measures and requirements to enhance social welfare and educational opportunities.', 'The French Law No. 2001-624 of July 17, 2001, focuses on various social, educational, and cultural provisions. It includes measures for unemployment compensation, reserve fund for pensioners, provisions for youth and popular education, and support for education and communication. The law aims to promote professional reintegration, aid geographical mobility, provide hiring incentives, offer training aid, and support actions for reclassification of employees. The policy targets individuals seeking employment, employers, training organizations, and the National Employment Agency. It outlines specific measures and requirements to enhance social welfare and educational opportunities.', 'The French Law No. 2001-624 of July 17, 2001, focuses on various social, educational, and cultural provisions. It includes measures for unemployment compensation, reserve fund for pensioners, provisions for youth and popular education, and support for education and communication. The law aims to promote professional reintegration, aid geographical mobility, provide hiring incentives, offer training aid, and support actions for reclassification of employees. The policy targets individuals seeking employment, employers, training organizations, and the National Employment Agency. It outlines specific measures and requirements to enhance social welfare and educational opportunities.', 'France', 'climate', 'in_force', '2001-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_3', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'france']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('438109b5-2bfc-5df8-be6e-02f86efcc2ee', 'France Law of May 9, 2001 relating to professional', 'Law no. 2001-397 of May 9, 2001 relating to professional equality between women and men', 'This document outlines the law no. 2001-397 of May 9, 2001 relating to professional equality between women and men.', 'This document outlines the law no. 2001-397 of May 9, 2001 relating to professional equality between women and men.', 'This document outlines the law no. 2001-397 of May 9, 2001 relating to professional equality between women and men.', 'France', 'social', 'in_force', '2001-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_30', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg5', 'france', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bc613619-70e2-552a-a023-151403793035', 'France Recommendations of the Committee on corporate governance', 'Recommendations of the Committee on corporate governance 1999', 'The 1999 Recommendations of the Committee on corporate governance in France focus on enhancing transparency and accountability in listed companies. Key recommendations include allowing the separation of the chairman and CEO roles, disclosing compensation details of corporate officers, and reporting on stock-option plans. The policy aims to improve corporate governance practices and increase shareholder confidence in the French market. It provides detailed guidelines on board structures, disclosures, and director responsibilities.', 'The 1999 Recommendations of the Committee on corporate governance in France focus on enhancing transparency and accountability in listed companies. Key recommendations include allowing the separation of the chairman and CEO roles, disclosing compensation details of corporate officers, and reporting on stock-option plans. The policy aims to improve corporate governance practices and increase shareholder confidence in the French market. It provides detailed guidelines on board structures, disclosures, and director responsibilities.', 'The 1999 Recommendations of the Committee on corporate governance in France focus on enhancing transparency and accountability in listed companies. Key recommendations include allowing the separation of the chairman and CEO roles, disclosing compensation details of corporate officers, and reporting on stock-option plans. The policy aims to improve corporate governance practices and increase shareholder confidence in the French market. It provides detailed guidelines on board structures, disclosures, and director responsibilities.', 'France', 'climate', 'in_force', '1999-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_22', ARRAY['guidance_frameworks', 'sdg16', 'france', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7c9611ad-d877-5937-ac18-b0a420b2892f', 'Boards of Directors of Listed Companies in France', 'The Boards of Directors of Listed Companies in France 1995', 'This document reviews principal issues concerning the membership, powers and operation of the boards of directors of French listed companies.', 'This document reviews principal issues concerning the membership, powers and operation of the boards of directors of French listed companies.', 'This document reviews principal issues concerning the membership, powers and operation of the boards of directors of French listed companies.', 'France', 'governance', 'in_force', '1995-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_21', ARRAY['france', 'mandatory', 'other sustainability policy', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aec64024-16e3-568b-b176-55e49e073e1d', 'Sustainable Finance Taxonomy for Georgia', 'Sustainable Finance Taxonomy for Georgia, 2022', 'Georgia''s 2022 Sustainable Finance Taxonomy helps banks and investors identify activities that benefit the environment and society (green, social, and both). Aligning with global standards, it guides funding towards a sustainable future for Georgia.', 'Georgia''s 2022 Sustainable Finance Taxonomy helps banks and investors identify activities that benefit the environment and society (green, social, and both). Aligning with global standards, it guides funding towards a sustainable future for Georgia.', 'Georgia''s 2022 Sustainable Finance Taxonomy helps banks and investors identify activities that benefit the environment and society (green, social, and both). Aligning with global standards, it guides funding towards a sustainable future for Georgia.', 'Georgia', 'climate', 'in_force', '2022-01-01'::date, 'Georgia', 'https://www.carrotsandsticks.org/policies/62_4', ARRAY['sdg2', 'sdg7', 'sdg11', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15', 'georgia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('248d189e-8a62-5e56-8266-48d6183768f6', 'Georgia Order № Regulation on Loan Classification and Reporting', 'Order № 93/04 Regulation on Loan Classification and Reporting according to the Sustainable Finance Taxonomy', 'The purpose of the “Regulation on Loan Classification and Reporting according to the Sustainable Finance Taxonomy” is to develop a loan classification system for commercial banks based on the sustainable finance taxonomy.', 'The purpose of the “Regulation on Loan Classification and Reporting according to the Sustainable Finance Taxonomy” is to develop a loan classification system for commercial banks based on the sustainable finance taxonomy.', 'The purpose of the “Regulation on Loan Classification and Reporting according to the Sustainable Finance Taxonomy” is to develop a loan classification system for commercial banks based on the sustainable finance taxonomy.', 'Georgia', 'climate', 'in_force', '2022-01-01'::date, 'Georgia', 'https://www.carrotsandsticks.org/policies/62_5', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'georgia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c07e1c1-486c-57ba-8376-acf01e53b297', 'Georgia ESG Reporting and Disclosure Principles', 'ESG Reporting and Disclosure Principles 2020', 'The ESG Reporting and Disclosure Principles 2020 is a set of guidelines developed by the National Bank of Georgia and the Organization for Economic Co-operation and Development (OECD) to promote environmental, social, and governance (ESG) reporting by financial institutions in Georgia. The Principles provide a framework for financial institutions to disclose information about their ESG performance, risks, and opportunities. They encourage financial institutions to integrate ESG considerations into their business operations, risk management, and decision-making processes. The Principles are designed to be voluntary and flexible, allowing financial institutions to tailor their reporting to their specific circumstances and priorities. They are also aligned with international best practices, including the OECD Guidelines for Multinational Enterprises and the United Nations Principles for Responsible Investment. Overall, the ESG Reporting and Disclosure Principles 2020 aim to promote transparency and accountability in ESG reporting by financial institutions in Georgia. They provide a useful tool for financial institutions to assess and communicate their ESG performance to stakeholders, and to promote sustainable and responsible business practices in the Georgian financial sector.', 'The ESG Reporting and Disclosure Principles 2020 is a set of guidelines developed by the National Bank of Georgia and the Organization for Economic Co-operation and Development (OECD) to promote environmental, social, and governance (ESG) reporting by financial institutions in Georgia. The Principles provide a framework for financial institutions to disclose information about their ESG p