INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('36a69fcd-0b57-50fb-bcc0-46baba44a42f', 'Roadmap for Sustainable Finance in Georgia', 'Roadmap for Sustainable Finance in Georgia', 'The Sustainable Finance Roadmap sets out the list of planned actions by the NBG regarding the sustainable finance development. The roadmap summarizes all the possible changes that the NBG intends to implement in the near future with the corresponding timeframe. The ultimate goal of this roadmap is to provide a credible, predictable and stable regulatory framework and prepare the market for transitioning to sustainable finance. The roadmap aims to support incorporation of sustainability issues into decision-making by providing coherent and consistent actions and allowing time for the system to adapt.', 'The Sustainable Finance Roadmap sets out the list of planned actions by the NBG regarding the sustainable finance development. The roadmap summarizes all the possible changes that the NBG intends to implement in the near future with the corresponding timeframe. The ultimate goal of this roadmap is to provide a credible, predictable and stable regulatory framework and prepare the market for transitioning to sustainable finance. The roadmap aims to support incorporation of sustainability issues into decision-making by providing coherent and consistent actions and allowing time for the system to adapt.', 'The Sustainable Finance Roadmap sets out the list of planned actions by the NBG regarding the sustainable finance development. The roadmap summarizes all the possible changes that the NBG intends to implement in the near future with the corresponding timeframe. The ultimate goal of this roadmap is to provide a credible, predictable and stable regulatory framework and prepare the market for transitioning to sustainable finance. The roadmap aims to support incorporation of sustainability issues into decision-making by providing coherent and consistent actions and allowing time for the system to adapt.', 'Georgia', 'climate', 'in_force', '2019-01-01'::date, 'Georgia', 'https://www.carrotsandsticks.org/policies/62_2', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'georgia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a666adbd-6a93-5a30-89d8-48cbf32ac652', 'Georgia Corporate Governance Code for Commercial Banks', 'Corporate Governance Code for Commercial Banks 2009', 'The purpose of this Code is to help banks to implement effective corporate governance mechanisms characterized by separation of responsibilities, effective decision making, protection of shareholders’ rights, effective treatment of conflicts of interest, public disclosure of information, cheks and balances and so on, in order to ensure effective protection of shareholder, depositor, creditor, investor, and public interests.', 'The purpose of this Code is to help banks to implement effective corporate governance mechanisms characterized by separation of responsibilities, effective decision making, protection of shareholders’ rights, effective treatment of conflicts of interest, public disclosure of information, cheks and balances and so on, in order to ensure effective protection of shareholder, depositor, creditor, investor, and public interests.', 'The purpose of this Code is to help banks to implement effective corporate governance mechanisms characterized by separation of responsibilities, effective decision making, protection of shareholders’ rights, effective treatment of conflicts of interest, public disclosure of information, cheks and balances and so on, in order to ensure effective protection of shareholder, depositor, creditor, investor, and public interests.', 'Georgia', 'governance', 'in_force', '2009-01-01'::date, 'Georgia', 'https://www.carrotsandsticks.org/policies/62_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'georgia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('69ddd65e-1a2c-5f57-b9db-0857b9753e33', 'Germany Final Report Commission for Low-Bureaucracy Implementation of the', 'Final Report Commission for Low-Bureaucracy Implementation of the Pay Transparency Directive', 'The Final Report by the Commission for Low-Bureaucracy Implementation of the Pay Transparency Directive in Germany addresses the need for equal pay for equal work. It focuses on implementing transparency measures while minimizing administrative burden for companies with over 100 employees. Target audience: government, businesses, employees.', 'The Final Report by the Commission for Low-Bureaucracy Implementation of the Pay Transparency Directive in Germany addresses the need for equal pay for equal work. It focuses on implementing transparency measures while minimizing administrative burden for companies with over 100 employees. Target audience: government, businesses, employees.', 'The Final Report by the Commission for Low-Bureaucracy Implementation of the Pay Transparency Directive in Germany addresses the need for equal pay for equal work. It focuses on implementing transparency measures while minimizing administrative burden for companies with over 100 employees. Target audience: government, businesses, employees.', 'Germany', 'climate', 'in_force', '2025-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_77', ARRAY['germany', 'regulations', 'mandatory', 'sdg5', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('92364cc5-c5b9-5507-920e-fc5795f513e1', 'Germany Law implementing Directive (EU) on corporate sustainability reporting', 'Law implementing Directive (EU) 2022/2464 on corporate sustainability reporting as amended by Directive (EU) 2025/794', 'Germany''s law implements EU Directives 2022/2464 and 2025/794 on corporate sustainability reporting, aiming to assess companies'' sustainability contributions. The policy targets investors, consumers, NGOs, and aims to ease reporting burdens while aligning with the European Green Deal and UN Sustainable Development Goals.', 'Germany''s law implements EU Directives 2022/2464 and 2025/794 on corporate sustainability reporting, aiming to assess companies'' sustainability contributions. The policy targets investors, consumers, NGOs, and aims to ease reporting burdens while aligning with the European Green Deal and UN Sustainable Development Goals.', 'Germany''s law implements EU Directives 2022/2464 and 2025/794 on corporate sustainability reporting, aiming to assess companies'' sustainability contributions. The policy targets investors, consumers, NGOs, and aims to ease reporting burdens while aligning with the European Green Deal and UN Sustainable Development Goals.', 'Germany', 'climate', 'in_force', '2025-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_79', ARRAY['sdg13', 'germany', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00dd5a6f-fc49-57b7-853c-f2cd50f533d1', 'Germany Draft law on corporate sustainability reporting amended', 'Draft law on corporate sustainability reporting amended by Directive (EU) 2025/794', 'The draft law aims to implement the EU Directive 2022/2464 on corporate sustainability reporting, amended by Directive 2025/794, ensuring Germany meets its EU obligations for sustainability reporting. It applies to companies required to report on their sustainability contributions, allowing stakeholders to assess their impact. The law introduces significant simplifications to reduce bureaucratic burdens, particularly for smaller companies, and delays the reporting timeline for certain groups. The initiative is part of the European Green Deal and aligns with the UN''s 2030 Agenda for Sustainable Development.', 'The draft law aims to implement the EU Directive 2022/2464 on corporate sustainability reporting, amended by Directive 2025/794, ensuring Germany meets its EU obligations for sustainability reporting. It applies to companies required to report on their sustainability contributions, allowing stakeholders to assess their impact. The law introduces significant simplifications to reduce bureaucratic burdens, particularly for smaller companies, and delays the reporting timeline for certain groups. The initiative is part of the European Green Deal and aligns with the UN''s 2030 Agenda for Sustainable Development.', 'The draft law aims to implement the EU Directive 2022/2464 on corporate sustainability reporting, amended by Directive 2025/794, ensuring Germany meets its EU obligations for sustainability reporting. It applies to companies required to report on their sustainability contributions, allowing stakeholders to assess their impact. The law introduces significant simplifications to reduce bureaucratic burdens, particularly for smaller companies, and delays the reporting timeline for certain groups. The initiative is part of the European Green Deal and aligns with the UN''s 2030 Agenda for Sustainable Development.', 'Germany', 'climate', 'in_force', '2025-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_80', ARRAY['sdg13', 'germany', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2284671f-167d-5f8d-bc30-3be53941c181', 'Germany Commercial Code', 'Commercial Code', 'The German Commercial Code outlines regulations for merchants and commercial activities. It defines merchants, registration requirements, and applies to commercial partnerships. The policy targets businesses engaged in trade and commerce in Germany to ensure compliance with legal standards.', 'The German Commercial Code outlines regulations for merchants and commercial activities. It defines merchants, registration requirements, and applies to commercial partnerships. The policy targets businesses engaged in trade and commerce in Germany to ensure compliance with legal standards.', 'The German Commercial Code outlines regulations for merchants and commercial activities. It defines merchants, registration requirements, and applies to commercial partnerships. The policy targets businesses engaged in trade and commerce in Germany to ensure compliance with legal standards.', 'Germany', 'governance', 'in_force', '2023-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_78', ARRAY['sdg17', 'mandatory', 'germany', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7960602f-9708-5255-9edc-fc16fe32b3da', 'Germany EcoLogistics Low Carbon Action Plan for Urban Freight', 'EcoLogistics Low Carbon Action Plan for Urban Freight (LCAP-UF)', 'This guidebook covers eight vital steps in the process of developing an LCAP-UF. The first phase is analyzing the current scenario, which this guidebook refers to as ‘Baseline Information’. The following steps include: identification of stakeholders engagement; defining low carbon target scenarios, defining vision, city goals and project goals; defining actions and demonstration projects; defining key performance indicators (KPIs); implementation and stakeholder roles. The final phase included in this guidebook is the adoption of the LCAP-UF.', 'This guidebook covers eight vital steps in the process of developing an LCAP-UF. The first phase is analyzing the current scenario, which this guidebook refers to as ‘Baseline Information’. The following steps include: identification of stakeholders engagement; defining low carbon target scenarios, defining vision, city goals and project goals; defining actions and demonstration projects; defining key performance indicators (KPIs); implementation and stakeholder roles. The final phase included in this guidebook is the adoption of the LCAP-UF.', 'This guidebook covers eight vital steps in the process of developing an LCAP-UF. The first phase is analyzing the current scenario, which this guidebook refers to as ‘Baseline Information’. The following steps include: identification of stakeholders engagement; defining low carbon target scenarios, defining vision, city goals and project goals; defining actions and demonstration projects; defining key performance indicators (KPIs); implementation and stakeholder roles. The final phase included in this guidebook is the adoption of the LCAP-UF.', 'Germany', 'climate', 'in_force', '2021-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_59', ARRAY['sdg13', 'other sustainability policy', 'germany', 'regulations', 'sdg11', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5dd92202-d82f-5666-a0c2-d7f12a71ee48', 'Germany Global Organic Textile Standard (GOTS) Version 6.0', 'Global Organic Textile Standard (GOTS) Version 6.0', 'The aim of this Standard is to define requirements to ensure organic status of textiles, from harvesting of the raw materials, through environmentally and socially responsible manufacturing up to labelling in order to provide a credible assurance to the end consumer.', 'The aim of this Standard is to define requirements to ensure organic status of textiles, from harvesting of the raw materials, through environmentally and socially responsible manufacturing up to labelling in order to provide a credible assurance to the end consumer.', 'The aim of this Standard is to define requirements to ensure organic status of textiles, from harvesting of the raw materials, through environmentally and socially responsible manufacturing up to labelling in order to provide a credible assurance to the end consumer.', 'Germany', 'governance', 'in_force', '2021-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_64', ARRAY['voluntary_frameworks', 'germany', 'other sustainability policy', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('57c41c78-3ed9-5304-910e-f424fac2a69e', 'Germany Build Forward Better', 'Build Forward Better, 2021', 'This briefing takes a closer look at instruments that aim to serve as orientation and provide an empirical basis to the pursuit of a Green Recovery.', 'This briefing takes a closer look at instruments that aim to serve as orientation and provide an empirical basis to the pursuit of a Green Recovery.', 'This briefing takes a closer look at instruments that aim to serve as orientation and provide an empirical basis to the pursuit of a Green Recovery.', 'Germany', 'climate', 'in_force', '2021-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_65', ARRAY['sdg2', 'other sustainability policy', 'germany', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0f9cd586-05cd-59d9-9a28-31f63d4a3215', 'Germany Draft of a first law to amend the', 'Draft of a first law to amend the Federal Climate Protection Act', 'The "First Act to Amend the Federal Climate Protection Act" strengthens Germany’s legislative framework for achieving national and international climate targets. Prompted by a ruling from the Federal Constitutional Court in 2021, the amendment introduces more ambitious greenhouse gas (GHG) reduction goals, setting a target of at least 65% reduction by 2030 and 88% by 2040 compared to 1990 levels, aiming for net-zero emissions by 2045. It adjusts permissible annual emissions for specific sectors, including energy, industry, and agriculture, ensuring compliance with national targets. The amendment mandates the creation of concrete reduction pathways for post-2030 periods and enhances the role of the Expert Council on Climate Issues. It emphasizes transparency, regular reporting, and public consultation in developing climate strategies. By providing clear directives and aligning with EU policies, the amendment aims to secure intergenerational equity and sustainable development.', 'The "First Act to Amend the Federal Climate Protection Act" strengthens Germany’s legislative framework for achieving national and international climate targets. Prompted by a ruling from the Federal Constitutional Court in 2021, the amendment introduces more ambitious greenhouse gas (GHG) reduction goals, setting a target of at least 65% reduction by 2030 and 88% by 2040 compared to 1990 levels, aiming for net-zero emissions by 2045. It adjusts permissible annual emissions for specific sectors, including energy, industry, and agriculture, ensuring compliance with national targets. The amendment mandates the creation of concrete reduction pathways for post-2030 periods and enhances the role of the Expert Council on Climate Issues. It emphasizes transparency, regular reporting, and public consultation in developing climate strategies. By providing clear directives and aligning with EU policies, the amendment aims to secure intergenerational equity and sustainable development.', 'The "First Act to Amend the Federal Climate Protection Act" strengthens Germany’s legislative framework for achieving national and international climate targets. Prompted by a ruling from the Federal Constitutional Court in 2021, the amendment introduces more ambitious greenhouse gas (GHG) reduction goals, setting a target of at least 65% reduction by 2030 and 88% by 2040 compared to 1990 levels, aiming for net-zero emissions by 2045. It adjusts permissible annual emissions for specific sectors, including energy, industry, and agriculture, ensuring compliance with national targets. The amendment mandates the creation of concrete reduction pathways for post-2030 periods and enhances the role of the Expert Council on Climate Issues. It emphasizes transparency, regular reporting, and public consultation in developing climate strategies. By providing clear directives and aligning with EU policies, the amendment aims to secure intergenerational equity and sustainable development.', 'Germany', 'climate', 'in_force', '2021-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_66', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'germany', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('488feb5f-4ea0-5582-9926-28ae5a3330b2', 'Germany Resolution recommendation and report of the Committee', 'Resolution recommendation and report of the Committee on Labor and Social Affairs (11th Committee)', 'This document is concerned with a resolution recommendation and report of the Committee on Labor and Social Affairs (11th Committee).', 'This document is concerned with a resolution recommendation and report of the Committee on Labor and Social Affairs (11th Committee).', 'This document is concerned with a resolution recommendation and report of the Committee on Labor and Social Affairs (11th Committee).', 'Germany', 'climate', 'in_force', '2021-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_67', ARRAY['guidance_frameworks', 'voluntary', 'germany', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('33245381-7b90-5a5b-becf-245ea8be2e42', 'Germany Draft Law on Corporate Due Diligence in Supply', 'Draft Law on Corporate Due Diligence in Supply Chains', 'The Gesetzentwurf der Bundesregierung über die unternehmerischen Sorgfaltspflichten in Lieferketten is a German government draft law proposing to establish mandatory due diligence obligations for companies with regards to human rights and environmental issues in their supply chains. The proposed legislation requires companies above a certain size to conduct risk assessments and take appropriate measures to prevent human rights violations, environmental harm, and other negative impacts in their supply chains. Companies will also be required to set up grievance mechanisms and report on their due diligence activities. The law is designed to apply to German companies with a certain number of employees, as well as foreign companies supplying goods or services to the German market. Companies that fail to comply with the law could face fines, liability claims, and other penalties. The draft law aims to promote sustainable and responsible business practices, and to ensure that companies operating in Germany respect human rights and environmental standards throughout their supply chains. It is currently under consideration in the German parliament and is expected to be enacted in the near future.', 'The Gesetzentwurf der Bundesregierung über die unternehmerischen Sorgfaltspflichten in Lieferketten is a German government draft law proposing to establish mandatory due diligence obligations for companies with regards to human rights and environmental issues in their supply chains. The proposed legislation requires companies above a certain size to conduct risk assessments and take appropriate measures to prevent human rights violations, environmental harm, and other negative impacts in their supply chains. Companies will also be required to set up grievance mechanisms and report on their due diligence activities. The law is designed to apply to German companies with a certain number of employees, as well as foreign companies supplying goods or services to the German market. Companies that fail to comply with the law could face fines, liability claims, and other penalties. The draft law aims to promote sustainable and responsible business practices, and to ensure that companies operating in Germany respect human rights and environmental standards throughout their supply chains. It is currently under consideration in the German parliament and is expected to be enacted in the near future.', 'The Gesetzentwurf der Bundesregierung über die unternehmerischen Sorgfaltspflichten in Lieferketten is a German government draft law proposing to establish mandatory due diligence obligations for companies with regards to human rights and environmental issues in their supply chains. The proposed legislation requires companies above a certain size to conduct risk assessments and take appropriate measures to prevent human rights violations, environmental harm, and other negative impacts in their supply chains. Companies will also be required to set up grievance mechanisms and report on their due diligence activities. The law is designed to apply to German companies with a certain number of employees, as well as foreign companies supplying goods or services to the German market. Companies that fail to comply with the law could face fines, liability claims, and other penalties. The draft law aims to promote sustainable and responsible business practices, and to ensure that companies operating in Germany respect human rights and environmental standards throughout their supply chains. It is currently under consideration in the German parliament and is expected to be enacted in the near future.', 'Germany', 'climate', 'in_force', '2021-01-0