INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b1d82b7e-ced4-5d78-8e88-9ce463a05cbe', 'Germany Securities Trading Act (Securities Trading Act - WpHG)', 'Securities Trading Act (Securities Trading Act - WpHG)', 'This document is concerned with the German Securities Trading Act which was last amended by Article 8 paragraph 1 of the law of December 9, 2020 .', 'This document is concerned with the German Securities Trading Act which was last amended by Article 8 paragraph 1 of the law of December 9, 2020 .', 'This document is concerned with the German Securities Trading Act which was last amended by Article 8 paragraph 1 of the law of December 9, 2020 .', 'Germany', 'governance', 'in_force', '2020-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_32', ARRAY['germany', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dceecc05-459e-5a04-840d-519e0d76adfe', 'Germany Investing Sustainably in African Livestock Development: Opportunities and', 'Investing Sustainably in African Livestock Development: Opportunities and Trade-Offs', 'The objectives of this report are first to describe the patterns and changing structures of the Sub-Saharan Africa (SSA) livestock sector and secondly to explore innovations that can help to address the complex trade-offs involved in investing in the development of a sustainable livestock sector. The report reviews trends in consumption, production and trade of major livestock commodities and feed in the four subregions of SSA and presents an overview of key issues facing the sector.', 'The objectives of this report are first to describe the patterns and changing structures of the Sub-Saharan Africa (SSA) livestock sector and secondly to explore innovations that can help to address the complex trade-offs involved in investing in the development of a sustainable livestock sector. The report reviews trends in consumption, production and trade of major livestock commodities and feed in the four subregions of SSA and presents an overview of key issues facing the sector.', 'The objectives of this report are first to describe the patterns and changing structures of the Sub-Saharan Africa (SSA) livestock sector and secondly to explore innovations that can help to address the complex trade-offs involved in investing in the development of a sustainable livestock sector. The report reviews trends in consumption, production and trade of major livestock commodities and feed in the four subregions of SSA and presents an overview of key issues facing the sector.', 'Germany', 'climate', 'in_force', '2020-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_58', ARRAY['sdg2', 'sdg14', 'germany', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('483c49e9-b42d-5c21-8448-6283d9b2c62b', 'Germany Law implementing Regulation (EU) 2017/821 of the European', 'Law implementing Regulation (EU) 2017/821 of the European Parliament and of the Council of 17 May 2017 laying down supply chain due diligence obligations for Union importers of tin, tantalum, tungsten, their ores and gold from conflict and High-risk areas, 2020', 'Passed in 2020, this law requires importers of conflict minerals (tin, tantalum, tungsten, gold) to check their supply chains and mitigate risks. It aims to prevent conflict funding and ensure ethical sourcing.', 'Passed in 2020, this law requires importers of conflict minerals (tin, tantalum, tungsten, gold) to check their supply chains and mitigate risks. It aims to prevent conflict funding and ensure ethical sourcing.', 'Passed in 2020, this law requires importers of conflict minerals (tin, tantalum, tungsten, gold) to check their supply chains and mitigate risks. It aims to prevent conflict funding and ensure ethical sourcing.', 'Germany', 'climate', 'in_force', '2020-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_76', ARRAY['germany', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4424ec60-7788-5cea-baf1-390810637ffe', 'Germany German Corporate Governance Code', 'German Corporate Governance Code 2019', 'The German Corporate Governance Code (the “Code”) contains principles, recommendations and suggestions for the Management Board and the Supervisory Board that are intended to ensure that the company is managed in its best interests.', 'The German Corporate Governance Code (the “Code”) contains principles, recommendations and suggestions for the Management Board and the Supervisory Board that are intended to ensure that the company is managed in its best interests.', 'The German Corporate Governance Code (the “Code”) contains principles, recommendations and suggestions for the Management Board and the Supervisory Board that are intended to ensure that the company is managed in its best interests.', 'Germany', 'governance', 'in_force', '2019-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_11', ARRAY['guidance_frameworks', 'germany', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed1f18a4-4f49-5dbf-af18-2f425880174e', 'Germany Act to introduce a federal climate protection law', 'Act to introduce a federal climate protection law and to change other regulations', 'The "Federal Climate Protection Act (KSG)", adopted on December 12, 2019, establishes Germany’s framework for reducing greenhouse gas emissions and achieving climate neutrality by 2050. It sets binding annual emission reduction targets for specific sectors, including energy, industry, transport, buildings, agriculture, and waste. The Act aligns national objectives with the European Climate Law and the Paris Agreement. Key mechanisms include rigorous emissions monitoring, the creation of annual and biannual climate reports, and the implementation of corrective action plans whenG33 targets are exceeded. An independent Expert Council evaluates emission data and provides recommendations. Public bodies are expected to lead by example through sustainable operations, while private sectors are incentivized to innovate and reduce their emissions footprint. The Act ensures transparency by mandating detailed sectoral emission reporting and public disclosure.', 'The "Federal Climate Protection Act (KSG)", adopted on December 12, 2019, establishes Germany’s framework for reducing greenhouse gas emissions and achieving climate neutrality by 2050. It sets binding annual emission reduction targets for specific sectors, including energy, industry, transport, buildings, agriculture, and waste. The Act aligns national objectives with the European Climate Law and the Paris Agreement. Key mechanisms include rigorous emissions monitoring, the creation of annual and biannual climate reports, and the implementation of corrective action plans whenG33 targets are exceeded. An independent Expert Council evaluates emission data and provides recommendations. Public bodies are expected to lead by example through sustainable operations, while private sectors are incentivized to innovate and reduce their emissions footprint. The Act ensures transparency by mandating detailed sectoral emission reporting and public disclosure.', 'The "Federal Climate Protection Act (KSG)", adopted on December 12, 2019, establishes Germany’s framework for reducing greenhouse gas emissions and achieving climate neutrality by 2050. It sets binding annual emission reduction targets for specific sectors, including energy, industry, transport, buildings, agriculture, and waste. The Act aligns national objectives with the European Climate Law and the Paris Agreement. Key mechanisms include rigorous emissions monitoring, the creation of annual and biannual climate reports, and the implementation of corrective action plans whenG33 targets are exceeded. An independent Expert Council evaluates emission data and provides recommendations. Public bodies are expected to lead by example through sustainable operations, while private sectors are incentivized to innovate and reduce their emissions footprint. The Act ensures transparency by mandating detailed sectoral emission reporting and public disclosure.', 'Germany', 'climate', 'in_force', '2019-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_31', ARRAY['sdg2', 'sdg13', 'germany', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c564c62-ef9e-5995-b345-8ffa8cd69d26', 'Germany DVFA Scorecard for Corporate Governance', 'DVFA Scorecard for Corporate Governance', 'The DVFA Scorecard for Corporate Governance is a tool that investment professionals can use to get a good picture of a company''s corporate governance performance and compare it to others. The scorecard is not only based on the German Corporate Governance Code, but also takes international standards into account.', 'The DVFA Scorecard for Corporate Governance is a tool that investment professionals can use to get a good picture of a company''s corporate governance performance and compare it to others. The scorecard is not only based on the German Corporate Governance Code, but also takes international standards into account.', 'The DVFA Scorecard for Corporate Governance is a tool that investment professionals can use to get a good picture of a company''s corporate governance performance and compare it to others. The scorecard is not only based on the German Corporate Governance Code, but also takes international standards into account.', 'Germany', 'governance', 'in_force', '2019-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_43', ARRAY['other sustainability policy', 'germany', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ad291f14-61ad-55d3-b087-add8988d1f05', 'Germany Federal Climate Protection Act (KSG)', 'Federal Climate Protection Act (KSG)', 'The Federal Climate Protection Act (KSG) of Germany, adopted on December 12, 2019, establishes legally binding targets for reducing greenhouse gas (GHG) emissions across various sectors. Aligned with the Paris Agreement, the act aims to achieve GHG neutrality by 2045, with interim reduction targets of 65% by 2030 and 88% by 2040, compared to 1990 levels. The law mandates annual emission limits for sectors such as energy, industry, transport, buildings, agriculture, and waste management. It incorporates mechanisms for monitoring, reporting, and enforcement, including an independent Expert Council for Climate Issues to oversee compliance. Penalties and adjustment measures are triggered if sectors exceed their annual emission limits, ensuring accountability and progress.', 'The Federal Climate Protection Act (KSG) of Germany, adopted on December 12, 2019, establishes legally binding targets for reducing greenhouse gas (GHG) emissions across various sectors. Aligned with the Paris Agreement, the act aims to achieve GHG neutrality by 2045, with interim reduction targets of 65% by 2030 and 88% by 2040, compared to 1990 levels. The law mandates annual emission limits for sectors such as energy, industry, transport, buildings, agriculture, and waste management. It incorporates mechanisms for monitoring, reporting, and enforcement, including an independent Expert Council for Climate Issues to oversee compliance. Penalties and adjustment measures are triggered if sectors exceed their annual emission limits, ensuring accountability and progress.', 'The Federal Climate Protection Act (KSG) of Germany, adopted on December 12, 2019, establishes legally binding targets for reducing greenhouse gas (GHG) emissions across various sectors. Aligned with the Paris Agreement, the act aims to achieve GHG neutrality by 2045, with interim reduction targets of 65% by 2030 and 88% by 2040, compared to 1990 levels. The law mandates annual emission limits for sectors such as energy, industry, transport, buildings, agriculture, and waste management. It incorporates mechanisms for monitoring, reporting, and enforcement, including an independent Expert Council for Climate Issues to oversee compliance. Penalties and adjustment measures are triggered if sectors exceed their annual emission limits, ensuring accountability and progress.', 'Germany', 'climate', 'in_force', '2019-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_55', ARRAY['sdg2', 'sdg13', 'germany', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('77173aae-237d-5c7f-be45-ec1caee05a87', 'Germany Emerging lessons for mainstreaming Ecosystem-based Adaptation', 'Emerging lessons for mainstreaming Ecosystem-based Adaptation', 'This report intends to offer some of the insights and lessons learned during the ecosystem assessments in the partner countries as well as an explanation of some concepts presented and case studies presented as success stories.', 'This report intends to offer some of the insights and lessons learned during the ecosystem assessments in the partner countries as well as an explanation of some concepts presented and case studies presented as success stories.', 'This report intends to offer some of the insights and lessons learned during the ecosystem assessments in the partner countries as well as an explanation of some concepts presented and case studies presented as success stories.', 'Germany', 'climate', 'in_force', '2019-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_74', ARRAY['sdg13', 'other sustainability policy', 'germany', 'mandatory', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7ad99a5f-5007-5eea-8e5f-ae135721d0b7', 'Germany Climate Risk Assessment for Ecosystem-based Adaptation', 'Climate Risk Assessment for Ecosystem-based Adaptation', 'The "Climate Risk Assessment for Ecosystem-Based Adaptation" guidebook provides a structured framework for integrating biodiversity and ecosystem services into climate adaptation strategies. Published by GIZ in 2018, the guidebook is aimed at practitioners and policymakers involved in planning and implementing climate risk assessments. It adopts the IPCC AR5 risk concept, emphasizing social-ecological systems (SES), to align adaptation measures with disaster risk reduction (DRR). The guidebook outlines nine modular steps for conducting assessments, from preparing and scoping to identifying adaptation measures and monitoring. Key features include the use of impact chains to visualize risk pathways and a focus on ecosystem-based solutions as cost-effective, co-beneficial alternatives to conventional methods. The methodology supports spatial planning and decision-making at various levels, ensuring alignment with international frameworks like the Sendai Framework and the Paris Agreement.', 'The "Climate Risk Assessment for Ecosystem-Based Adaptation" guidebook provides a structured framework for integrating biodiversity and ecosystem services into climate adaptation strategies. Published by GIZ in 2018, the guidebook is aimed at practitioners and policymakers involved in planning and implementing climate risk assessments. It adopts the IPCC AR5 risk concept, emphasizing social-ecological systems (SES), to align adaptation measures with disaster risk reduction (DRR). The guidebook outlines nine modular steps for conducting assessments, from preparing and scoping to identifying adaptation measures and monitoring. Key features include the use of impact chains to visualize risk pathways and a focus on ecosystem-based solutions as cost-effective, co-beneficial alternatives to conventional methods. The methodology supports spatial planning and decision-making at various levels, ensuring alignment with international frameworks like the Sendai Framework and the Paris Agreement.', 'The "Climate Risk Assessment for Ecosystem-Based Adaptation" guidebook provides a structured framework for integrating biodiversity and ecosystem services into climate adaptation strategies. Published by GIZ in 2018, the guidebook is aimed at practitioners and policymakers involved in planning and implementing climate risk assessments. It adopts the IPCC AR5 risk concept, emphasizing social-ecological systems (SES), to align adaptation measures with disaster risk reduction (DRR). The guidebook outlines nine modular steps for conducting assessments, from preparing and scoping to identifying adaptation measures and monitoring. Key features include the use of impact chains to visualize risk pathways and a focus on ecosystem-based solutions as cost-effective, co-beneficial alternatives to conventional methods. The methodology supports spatial planning and decision-making at various levels, ensuring alignment with international frameworks like the Sendai Framework and the Paris Agreement.', 'Germany', 'climate', 'in_force', '2018-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_72', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'germany', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('551cd2b1-d956-5922-aa6c-e6eb23d18853', 'Germany German Corporate Governance Code (as amended on February', 'German Corporate Governance Code (as amended on February 7, 2017 with decisions from the plenary meeting of February 7, 2017)', 'This Code highlights the obligation of the Management and Supervisory Boards to ensure the continued existence of the company and its sustainable value creation in line with the principles of the social market economy (the company’s best interests).', 'This Code highlights the obligation of the Management and Supervisory Boards to ensure the continued existence of the company and its sustainable value creation in line with the principles of the social market economy (the company’s best interests).', 'This Code highlights the obligation of the Management and Supervisory Boards to ensure the continued existence of the company and its sustainable value creation in line with the principles of the social market economy (the company’s best interests).', 'Germany', 'governance', 'in_force', '2017-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_19', ARRAY['guidance_frameworks', 'germany', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
